-- Senate control initiatives: each file is an initiative, not an intervention.
CREATE TABLE public.senate_control_initiatives (
 id text PRIMARY KEY,
 legislature integer NOT NULL CHECK(legislature=15),
 number text NOT NULL CHECK(number ~ '^[0-9]{3}/[0-9]{6}$'),
 kind text NOT NULL CHECK(kind IN ('motion','interpellation')),
 presentation_date date,title text NOT NULL,evidence jsonb NOT NULL,
 UNIQUE(legislature,number),CHECK(id=legislature::text||'/'||number)
);
ALTER TABLE public.senate_control_initiatives ENABLE ROW LEVEL SECURITY;
CREATE POLICY senate_control_read ON public.senate_control_initiatives FOR SELECT TO anon,authenticated USING(true);
GRANT SELECT ON public.senate_control_initiatives TO anon,authenticated;
GRANT ALL ON public.senate_control_initiatives TO service_role;
CREATE TABLE public.senate_control_coverage(scope text PRIMARY KEY CHECK(scope='senate-15-housing'),metadata jsonb NOT NULL);
ALTER TABLE public.senate_control_coverage ENABLE ROW LEVEL SECURITY;
CREATE POLICY senate_control_coverage_read ON public.senate_control_coverage FOR SELECT TO anon,authenticated USING(true);
GRANT SELECT ON public.senate_control_coverage TO anon,authenticated;
GRANT ALL ON public.senate_control_coverage TO service_role;
